const issues = [];
const re = /(iphone|ipad|imac|ios|macos|watchos|ipados|airpods)\s*\d*\s*(pro\s*max|promax|pro|plus|mini|max|air|se|e)?/gi;
const correctBrand = { iphone:'iPhone', ipad:'iPad', imac:'iMac', ios:'iOS', macos:'macOS', watchos:'watchOS', ipados:'iPadOS', airpods:'AirPods' };
const sufMap = { 'promax':'Pro Max','pro':'Pro','plus':'Plus','mini':'mini','max':'Max','air':'Air','se':'SE','e':'e' };
let m;
while ((m = re.exec(text)) !== null) {
  const brand = correctBrand[m[1].toLowerCase()];
  const numMatch = m[0].match(/\d+/);
  const num = numMatch ? numMatch[0] : '';
  const suf = m[2] ? sufMap[m[2].toLowerCase().replace(/\s+/g,'')] : '';
  let ideal = brand;
  if (num) ideal += ' ' + num;
  if (suf) ideal += ' ' + suf;
  if (m[0] !== ideal) issues.push({ index: m.index, length: m[0].length, snippet: m[0], fix: ideal });
}
// 苹果 17 这种中文写法
const re2 = /苹果\s*(\d+)\s*(pro\s*max|pro|plus|mini|max)?/gi;
while ((m = re2.exec(text)) !== null) {
  const num = m[1];
  const suf = m[2] ? ' ' + sufMap[m[2].toLowerCase().replace(/\s+/g,'')] : '';
  issues.push({ index: m.index, length: m[0].length, snippet: m[0], fix: 'iPhone ' + num + suf });
}
return issues;

const issues = [];
const cnNum = '[一二三四五六七八九十百千万两]';
const measure = '(个|次|位|名|分钟|小时|天|周|月|年|岁|元|块|斤|公里|米|厘米|毫米|款|种|遍|轮|项|条|篇|套|张|场|波|步|杯|份|册|页|秒|刻)';
const whitelist = ['一带一路','三国','十全十美','五一','十一','九九','三五成群','七七八八','一二三','再三','一年半载','三言两语'];
const re = new RegExp(cnNum + '+' + measure, 'g');
let m;
while ((m = re.exec(text)) !== null) {
  const around = text.slice(Math.max(0, m.index - 2), m.index + m[0].length + 2);
  if (whitelist.some(w => around.includes(w))) continue;
  issues.push({ index: m.index, length: m[0].length, snippet: m[0], fix: '请改用阿拉伯数字（如「3 个」）' });
}
const reDi = new RegExp('第' + cnNum + '+(次|个|位|届|期|代|版|名|轮|季|集|关|批)', 'g');
while ((m = reDi.exec(text)) !== null) {
  issues.push({ index: m.index, length: m[0].length, snippet: m[0], fix: '建议改为「第 X」用阿拉伯数字' });
}
return issues;

const issues = [];
const re = /[\u4e00-\u9fa5]\s*([,.;:!?])\s*[\u4e00-\u9fa5]/g;
const map = { ',':'，', '.':'。', ';':'；', ':':'：', '!':'！', '?':'？' };
let m;
while ((m = re.exec(text)) !== null) {
  const punc = m[1];
  issues.push({ index: m.index, length: m[0].length, snippet: m[0], fix: m[0].replace(punc, map[punc]) });
}
return issues;
